private BackendLifecycle Lifecycle(
    bool healthy,
    BackendStartOptions? options = null,
    List<string>? log = null,
    Func<BackendPaths, Action<string>, BackendVenv.Result>? ensureVenv = null)
{
    var paths = Paths();
    Directory.CreateDirectory(paths.Scratch);
